html_table = '<table><tr><th>Country</th><th>Code</th></tr><tr><td>India</td><td>IN</td></tr><tr><td>Germany</td><td>DE</td></tr></table>'
soup = BeautifulSoup(html_table, 'html.parser')
country_map = {}
for row in soup.find_all('tr'):
    cols = row.find_all('td')
    if len(cols) == 2:
        country_map[cols[0].text] = cols[1].text
print(country_map)

